head=f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#143bff"><title>Scribble / 002 — Recycle</title><meta name="description" content="Gözden çıkarma. Yaşam, atık ve yeniden dönüş üzerine bir dijital farkındalık deneyimi."><meta property="og:title" content="Scribble / 002 — Recycle"><meta property="og:description" content="Gözden çıkarma. Yaşam devam etsin, atığın değil."><meta property="og:image" content="{url('ocean')}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="data:image/svg+xml;base64,"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preconnect" href="https://images.unsplash.com"><link rel="stylesheet" href="{fonturl}"><link rel="stylesheet" href="recycle.css?v=orbital-002?v=20261113"><script src="recycle.js?v=orbital-002?v=20261113" defer></script></head><body><div id="top"></div>'''
nav=f'''<a class="skip" href="#main">İçeriğe geç / Skip to content</a><header class="site-header"><a class="brand" href="index.html" aria-label="Scribble Recycle">{mark}<span>scribble</span></a><span class="header-edition">002 : RECYCLE</span><span class="header-clock" aria-hidden="true">00 : 00 : 00</span><a class="header-link" href="index.html#loop">{t('DÖNGÜ','THE CYCLE')}</a><a class="header-link" href="index.html#about">{t('BİLGİ','ABOUT')}</a><button class="language" aria-label="Switch to English">EN</button><button class="menu-open" aria-label="Menüyü aç / Open menu" aria-expanded="false">{t('MENÜ','MENU')} +</button></header><dialog class="menu-dialog" aria-label="Menü / Menu"><div class="menu-top"><span>SCRIBBLE / 002</span><button class="dialog-close" aria-label="Menüyü kapat / Close menu">×</button></div><nav>'''+''.join(f'<a href="{href}"><small>{i:02}</small>{t(tr,en)}{a}</a>' for i,(href,tr,en) in enumerate([('index.html#life','YAŞAM','LIFE'),('index.html#trace','İZ','TRACE'),('index.html#loop','DÖNGÜ','CYCLE'),('index.html#action','HAREKET','ACTION'),('references.html','KAYNAKLAR','SOURCES')],1))+'''</nav><button class="language menu-language" aria-label="Switch to English">EN</button></dialog>'''
foot=f'''<footer id="about"><div class="footer-info"><div class="footer-intro"><span class="eyebrow">{t('BİTİŞ DEĞİL.','NOT THE END.')}</span><p>{t('Yaşam devam etsin.','Let life go on.')}<br>{t('Atığın değil.','Not waste.')}</p>{mark}</div><div class="footer-row"><span>{t('BU DÜNYA HAKKINDA','ABOUT THIS WORLD')}</span><p>{t('Scribble / 002, tüketim alışkanlıklarına ve geri dönüşüme başka bir yerden bakan bir farkındalık projesi. Bir şişenin hikâyesi, elimizden çıktığı yerde bitmiyor.','Scribble / 002 is an awareness project looking at consumption and recycling from another perspective. A bottle’s story does not end when it leaves our hands.')}</p></div><div class="footer-row"><span>{t('BİR MARKA. BAŞKA BİR DÜNYA.','ONE BRAND. ANOTHER WORLD.')}</span><p>{t('Scribble her projede başka bir kimliğe bürünür. İsim ve logo aynı kalır. Bu kez odağımız; doğa, atık ve döngü.','Scribble takes on a different identity in every project. The name and logo stay. This time, the focus is nature, waste and circulation.')}</p></div><div class="footer-row"><span>{t('BAĞLANTILAR','QUICK LINKS')}</span><div class="footer-links"><a href="references.html">{t('Kaynaklar & referanslar','Sources & references')}{a}</a><a href="https://github.com/scribble-worlds/scribble-recycle" target="_blank" rel="noopener">{t('Projenin kodları','Project source')}{a}</a><a href="https://github.com/scribble-worlds" target="_blank" rel="noopener">{t('Scribble dünyaları','Scribble worlds')}{a}</a><button class="motion-toggle" aria-pressed="false">{t('Hareketi duraklat','Pause motion')} ||</button></div></div><div class="footer-row footer-final"><span>© 2026 / MUHAM²ED</span><p>{t('Bir tasarım ve geliştirme çalışması.','A design and development concept.')}<br><a href="#top">{t('Başa dön','Back to top')} ↑</a></p></div></div><a class="footer-billboard" href="#top" aria-label="Başa dön / Back to top"><span class="footer-word">SCRIBBLE</span><span class="footer-hover" aria-hidden="true"><img src="{url('turtle',960)}" alt="" width="240" height="160"><span>002 / RECYCLE</span></span></a><div class="footer-bottom"><span>{t('DÖNÜŞTÜR / YENİDEN KULLAN / YENİDEN DÜŞÜN','RECYCLE / REUSE / RETHINK')}</span><span>002 — 2026</span><span>{t('SONRAKİ HAYATINA.','TO ITS NEXT LIFE.')}</span></div></footer>'''
hero=f'''<section class="hero" aria-labelledby="hero-title"><div class="hero-frames">'''+''.join(f'<div class="hero-frame {"active" if i==0 else ""}" data-frame="{i}">{photo(key,"hero-photo",i==0)}</div>' for i,key in enumerate(photos))+f'''</div><div class="hero-meta"><span>SCRIBBLE® / {t('GERİ DÖNÜŞÜM FARKINDALIĞI','RECYCLING AWARENESS')}</span><p>{t('BİR KERE KULLANDIK.','USED FOR A MOMENT.')}<br>{t('SONSUZA DEK KALMASIN.','NOT HERE FOREVER.')}</p></div><h1 id="hero-title">{t('GÖZDEN ÇIKARMA.','DON’T LOOK AWAY.')}</h1><div class="hero-reel" aria-label="Görsel seçimi / Select a scene">'''+''.join(f'<button class="reel-item {"active" if i==0 else ""}" data-scene="{i}" aria-pressed="{"true" if i==0 else "false"}"><img src="{url(key,960)}" alt="" width="100" height="60"><span><small>{i+1:02} / {t(label,enlabel)}</small>{t(tr,en)}</span><i></i></button>' for i,(key,label,enlabel,tr,en) in enumerate([('ocean','OKYANUS','OCEAN','HER ŞEY BİRBİRİNE BAĞLI.','EVERYTHING IS CONNECTED.'),('turtle','YAŞAM','LIFE','BU BİR YAŞAM ALANI.','THIS IS A LIVING WORLD.'),('plastic','İZ','TRACE','ATTIĞIMIZ YER NERESİ?','WHERE IS AWAY?')]))+f'<a class="hero-explore" href="#intro">{t("İÇERİ DAL","DIVE IN")}{down}</a></div></section>'
intro=f'''<section class="intro" id="intro"><div class="label-row"><span>002 / RECYCLE</span><span>{t('BİR DÖNGÜ MESELESİ','A MATTER OF CIRCULATION')}</span><span>{t('KEŞFETMEK İÇİN KAYDIR','SCROLL TO EXPLORE')} ↓</span></div><div class="intro-type"><h2>{t('KULLANDIK.','WE USED IT.')}<br><span class="blue">{t('BİTMEDİ.','IT STAYS.')}</span></h2><div><p class="intro-statement">{t('Bir ambalajın bizimle işi biter. Dünya ile bitmez.','A wrapper’s time with us ends. Its time with the world does not.')}</p><p>{t('Ürettiğimiz, kullandığımız ve geride bıraktığımız her şeyin bir sonrası var. Bu sayfa, o sonrasına bakmak için.','Everything we make, use and leave behind has an afterlife. This page is a closer look at what comes next.')}</p><a class="text-link" href="#life">{t('İZİ TAKİP ET','FOLLOW THE TRACE')}{a}</a></div></div></section>'''
def chapter(n,id,key,label,enlabel,tr1,en1,tr2,en2,body,enbody):return f'''<section class="chapter" id="{id}"><div class="chapter-stage" id="panel-{id}"><div class="chapter-clip"><div class="chapter-label"><span>{n} / {t(label,enlabel)}</span><span>{t('FOTOĞRAF','PHOTOGRAPHY')}</span></div><button class="chapter-photo-button" data-lightbox="{url(key,3840)}" data-credit="{photos[key][1]} / Unsplash" aria-label="Görseli tam ekran aç / Open photograph"><div class="photo-inner">{photo(key,'chapter-photo')}</div><span class="photo-open">{t('YAKINDAN BAK','TAKE A CLOSER LOOK')} +</span></button><div class="photo-caption"><span>© {photos[key][1]} / Unsplash</span><a href="references.html#visuals">{t('GÖRSEL KAYNAĞI','IMAGE SOURCE')}{a}</a></div></div></div><button class="chapter-title" aria-expanded="true" aria-controls="panel-{id}"><span class="chapter-number">{n}</span><h2>{t(tr1,en1)}<br>{t(tr2,en2)}</h2><span class="chapter-arrow">{down}</span></button><div class="chapter-note"><span>{t(label,enlabel)}</span><p>{t(body,enbody)}</p></div></section>'''
life=chapter('01','life','turtle','YAŞAM','LIFE','BU BİR','THIS IS A','YAŞAM ALANI.','LIVING WORLD.','Kendimize küçük gördüğümüz şeylerin, başka canlıların dünyasında büyük bir yeri olabilir. Daha az atık, yaşam için daha fazla alan.','What seems small to us can take up a large place in another creature’s world. Less waste means more room for life.')
trace=chapter('02','trace','plastic','İZ','TRACE','GÖZDEN UZAK.','OUT OF SIGHT.','DÜNYADAN DEĞİL.','STILL IN THE WORLD.','Yanlış yönetilen atık; yağmur, rüzgâr ve akarsularla yaşam alanlarına taşınabilir. Çöp kutusunun dışındaki hikâye de bize ait.','Mismanaged waste can travel through rain, wind and rivers into living habitats. The story beyond the bin belongs to us too.')
water=f'''<section class="water-stat"><div class="stat-label"><span>UNEP / {t('YILLIK TAHMİN','ANNUAL ESTIMATE')}</span><a href="references.html#data">{t('KAYNAĞA GİT','VIEW SOURCE')}{a}</a></div><div class="water-stat-body"><strong>19–23<span>{t('MİLYON TON','MILLION TONNES')}</span></strong><p>{t('Her yıl göllere, nehirlere ve denizlere sızan plastik atık.','Plastic waste leaking into lakes, rivers and seas every year.')}<small>{t('Tüm su ekosistemlerini kapsayan tahmin; yalnızca okyanuslar değil.','Estimate covering aquatic ecosystems, not oceans alone.')}</small></p></div></section>'''
bottle='<svg viewBox="0 0 30 66" aria-hidden="true"><path d="M11 6h8v9c0 4 7 6 7 13v29c0 6-4 7-7 5l-4-1-4 1c-4 2-7 0-7-5V28c0-7 7-9 7-13Z"/><path d="M10 6V2h10v4M6 31h18M6 37h18M6 49h18M6 55h18M11 21l-3 6"/></svg>'
units=[];index=0
for col,rows in enumerate([1,2,3,4,5,6,8,10,12,14,16,19]):
 for row in range(rows):
  units.append(f'<span class="bottle-unit {"recycled" if index<9 else ""}" style="--x:{col};--y:{row}">{bottle}</span>');index+=1
loop=f'''<section class="loop" id="loop"><div class="label-row"><span>03 / {t('DÖNGÜ','CYCLE')}</span><span>{t('BİRİKİMDEN DÖNGÜYE','FROM ACCUMULATION TO CIRCULATION')}</span><span>OECD / 2019</span></div><div class="loop-title"><h2>{t('DÖNÜŞÜ MÜMKÜN.','A RETURN IS POSSIBLE.')}</h2><span class="orbit-icon" aria-hidden="true">↻</span></div><div class="loop-layout"><div class="loop-copy"><span class="loop-year">2019 / {t('DÜNYA','GLOBAL')}</span><strong class="recycle-number">%9</strong><h3>{t('GERİ DÖNÜŞTÜRÜLDÜ.','WAS RECYCLED.')}</h3><p>{t('Dünya genelindeki plastik atığın, toplama ve işleme kayıpları sonrasında geri dönüştürülen payı.','The share of global plastic waste actually recycled, after collection and processing losses.')}</p><button class="graph-toggle" aria-pressed="false">{t('O %9’U GÖR','SEE THAT 9%')}{a}</button><span class="graph-key">{t('HER ŞEKİL = PLASTİK ATIĞIN %1’İ','EACH SHAPE = 1% OF PLASTIC WASTE')}</span></div><div class="bottle-graph" aria-hidden="true">{''.join(units)}<span class="graph-baseline">{t('100 ŞEKİL / %100','100 SHAPES / 100%')}</span></div></div><div class="loop-bottom"><strong>353 <span>{t('MİLYON TON','MILLION TONNES')}</span></strong><p>{t('2019’da dünyada üretilen plastik atık. Geri dönüştürülmeyenin tamamı denize gitmez; yakma, depolama ve kontrolsüz yönetim de tablonun parçasıdır.','Plastic waste generated globally in 2019. Not all unrecycled waste enters the sea; incineration, landfill and mismanagement are also part of the picture.')}</p><a href="references.html#data">OECD / GLOBAL PLASTICS OUTLOOK{a}</a></div></section>'''
actions=[('DAHA AZ.','LESS.','İhtiyacın kadarını seç.','Choose what you need.','Tek kullanımlık ambalajı azalt. Alışverişe kendi çantanla git; gereksiz paketleme yerine daha az malzeme kullanan seçenekleri düşün.','Reduce single-use packaging. Bring your own bag; consider options that use less material.'),('TEKRAR.','AGAIN.','Bir kullanımdan fazlası.','More than a single use.','Güvenli ve amacına uygun olduğu sürece doldur, tamir et, paylaş. Bir eşyanın ömrünü uzatmak, yeni atık ihtiyacını azaltır.','Refill, repair and share when safe and appropriate. Extending an object’s life reduces the need for new waste.'),('DOĞRU YERE.','THE RIGHT PLACE.','Ayrıştırmak bir başlangıç.','Sorting is a beginning.','Ambalajı boşalt, yiyecek kalıntısını gider ve bulunduğun yerde kabul edilen malzemeleri ayır. Yerel toplama kuralları her yerde aynı değildir.','Empty packaging, remove food residue and separate materials accepted locally. Collection rules are not the same everywhere.')]
action=f'''<section class="action" id="action"><div class="label-row"><span>04 / {t('HAREKET','ACTION')}</span><span>{t('DÖNGÜYÜ SEN DEĞİŞTİR','CHANGE THE CYCLE')}</span><span>{t('BUGÜNDEN BAŞLA','START TODAY')}</span></div><div class="action-heading"><h2>{t('BAŞKA BİR','THERE IS')}<br>{t('YOLU VAR.','ANOTHER WAY.')}</h2><p>{t('En iyi atık, hiç oluşmayandır. Önce azalt. Sonra yeniden kullan. Geri dönüşüm, geriye kalan için.','The best waste is the waste never created. Reduce first. Then reuse. Recycle what remains.')}</p></div>'''+''.join(f'<details class="action-detail" {"open" if i==0 else ""}><summary><span>{i+1:02}</span><h3>{t(tr,en)}</h3><span class="plus">+</span></summary><div class="action-detail-body"><h4>{t(sub,ensub)}</h4><p>{t(body,enbody)}</p></div></details>' for i,(tr,en,sub,ensub,body,enbody) in enumerate(actions))+f'''<div class="material-guide"><div class="guide-intro"><h3>{t('NE, NEREYE?','WHAT GOES WHERE?')}</h3><span>{t('MALZEME REHBERİ','MATERIAL GUIDE')}</span></div><div class="material-tabs" role="tablist" aria-label="Malzeme rehberi / Material guide">'''+''.join(f'<button role="tab" id="tab-{key}" data-material="{key}" aria-selected="{"true" if i==0 else "false"}" aria-controls="material-panel" tabindex="{0 if i==0 else -1}">{t(tr,en)}</button>' for i,(key,tr,en) in enumerate([('plastic','PLASTİK','PLASTIC'),('glass','CAM','GLASS'),('paper','KÂĞIT','PAPER'),('metal','METAL','METAL')]))+f'''</div><div id="material-panel" role="tabpanel" aria-labelledby="tab-plastic" tabindex="0"><div><span id="material-label"></span><h4 id="material-title"></h4></div><div><p id="material-body"></p><p id="material-tip"></p></div></div><p class="local-note">{t('Ürünün üzerindeki kod, yerel sistemin onu kabul ettiğini tek başına göstermez. Belediyenin veya yetkili toplayıcının güncel talimatını kontrol et.','A code on a product alone does not mean your local system accepts it. Check the current instructions from your municipality or authorised collector.')} <a href="references.html#data">{t('KAYNAKLAR','SOURCES')}{a}</a></p></div></section>'''
lightbox=f'<dialog class="lightbox" aria-label="Fotoğraf görüntüleyici / Photograph viewer"><div class="lightbox-top"><span class="lightbox-credit"></span><button class="dialog-close" aria-label="Görseli kapat / Close photograph">{t("KAPAT","CLOSE")} ×</button></div><div class="lightbox-content"><img class="lightbox-image" alt=""></div><span class="lightbox-bottom">{t("FOTOĞRAF / ÖZGÜN KAYNAK","PHOTOGRAPHY / ORIGINAL SOURCE")}</span></dialog>'
(p/'index.html').write_text(head+nav+'<main id="main">'+hero+intro+life+trace+water+loop+action+'</main>'+foot+lightbox+'</body></html>')
archive=''.join(f'<article class="source-photo">{photo(key)}<div><h3>{v[1]}</h3><p>{v[2]} / {t("KAYNAK BOYUTU","SOURCE DIMENSIONS")}</p><a href="{v[3]}" target="_blank" rel="noopener">UNSPLASH / {t("ÖZGÜN FOTOĞRAF","ORIGINAL PHOTO")}{a}</a></div></article>' for key,v in photos.items())
refs=f'''<main class="source-page" id="main"><a class="text-link" href="index.html">← {t('DENEYİME DÖN','BACK TO THE EXPERIENCE')}</a><div class="source-heading"><span>002 / THE INDEX</span><h1>{t('İZİNİ SÜR.','TRACE IT BACK.')}</h1><p>{t('Fotoğraf, veri ve tasarım referansları.','Photography, data and design references.')}</p></div><section class="source-section" id="visuals"><h2>01 / {t('FOTOĞRAFLAR','PHOTOGRAPHY')}</h2><p>{t('Gerçek fotoğraflar, aşağıdaki özgün kaynaklardan sunulur. Ekrana göre 960, 1920 ve 3840 piksel seçenekleri kullanılır. Küçük Pinterest görselleri büyütülmemiştir.','Real photographs are served from the original sources below in 960, 1920 and 3840 pixel versions. Small Pinterest images have not been enlarged.')}</p><div class="source-photo-grid">{archive}</div><p>{t('Fotoğraflar ilgili fotoğrafçılara aittir ve Unsplash lisansı kapsamında kullanılır. Proje için destek veya ortaklık iddia edilmez.','Photographs belong to the credited photographers and are used under the Unsplash License. No endorsement or partnership is implied.')} <a href="https://unsplash.com/license" target="_blank" rel="noopener">UNSPLASH LICENSE{a}</a></p></section><section class="source-section" id="data"><h2>02 / {t('VERİLER','DATA')}</h2><article><h3>OECD / Global Plastics Outlook, 2022</h3><p>{t('2019, dünya: 353 milyon ton plastik atık; toplama ve işleme kayıpları sonrası %9 geri dönüşüm. 100 şekil toplam plastik atığı, vurgulanan 9 şekil geri dönüştürülen payı temsil eder. Şişe biçimi semboliktir; veri sadece PET şişelere ait değildir. Yükselen kompozisyon bir zaman serisi değildir.','Global, 2019: 353 million tonnes of plastic waste; 9% actually recycled after collection and processing losses. 100 shapes represent total plastic waste; 9 highlighted shapes represent the recycled share. The bottle form is symbolic, not PET-only data. The rising composition is not a time series.')}</p><a href="https://www.oecd.org/en/publications/2022/02/global-plastics-outlook_a653d1c9.html" target="_blank" rel="noopener">OECD{a}</a></article><article><h3>UNEP / Plastic pollution & marine litter</h3><p>{t('Yıllık 19–23 milyon ton tahmini; göl, nehir ve denizleri kapsayan su ekosistemlerine sızan plastik atıktır. Yalnızca okyanuslara ait değildir ve OECD’nin 2019 verileriyle toplanmaz.','The annual estimate of 19–23 million tonnes refers to plastic waste leaking into aquatic ecosystems, including lakes, rivers and seas. It is not oceans-only and is not added to OECD’s 2019 figures.')}</p><a href="https://www.unep.org/en/what-we-do/ocean-seas-and-coasts/ecosystem-degradation-pollution/plastic-pollution-marine-litter" target="_blank" rel="noopener">UNEP{a}</a></article><article><h3>US EPA / Reduce, reuse & recycling</h3><p>{t('Azaltma, yeniden kullanma, ambalajı boşaltma ve yerel kabul kurallarını kontrol etme için başvuru kaynağı. ABD’ye özgü kabul listeleri ve kutu renkleri Türkiye için genellenmez.','Reference for reducing, reusing, emptying packaging and checking local acceptance. US-specific lists and bin colours are not applied to Türkiye.')}</p><a href="https://www.epa.gov/plastics/what-you-can-do-reduce-plastic-waste" target="_blank" rel="noopener">EPA / REDUCE{a}</a><a href="https://www.epa.gov/recycle/how-do-i-recycle-common-recyclables" target="_blank" rel="noopener">EPA / RECYCLE{a}</a></article></section><section class="source-section"><h2>03 / {t('TASARIM REFERANSLARI','DESIGN REFERENCES')}</h2><div class="reference-links">'''+''.join(f'<a href="{u}" target="_blank" rel="noopener">{name}<span>{t(tr,en)}</span>{a}</a>' for name,u,tr,en in [('LAFOUR','https://lafour.com','Tam ekran fotoğraf, işaretli ince menü, görsel seçicisi','Full-screen imagery, marker-based navigation, scene selector'),('LAMENT','https://lament.tv','Büyük numaralı başlıklar, açılan medya, scroll akışı','Oversized numbered titles, expandable media, scroll flow'),('JARCOS','https://jarcos.work','Siyah bilgi satırları, beyaz büyük kelime işareti','Black information rows, white oversized wordmark'),('WEBINSPOO','https://webinspoo.com/?ref=darkmodedesign','Nesnelerle yükselen kompozisyon','Rising object composition')])+f'''</div></section><section class="source-section"><h2>04 / {t('İLHAM ARŞİVİ','INSPIRATION ARCHIVE')}</h2><p>{t('Aşağıdaki görseller bu sürümde sayfa fotoğrafı olarak kullanılmaz; ilham bağlantıları korunur.','The earlier images are not used as page photography in this version; inspiration links are retained.')}</p><div class="reference-links">'''+''.join(f'<a href="{u}" target="_blank" rel="noopener">{name}{a}</a>' for name,u in [('01 / Plastikten balıklar','https://www.pinterest.com/pin/719379740525159749/'),('02 / Acrylic Painting of Nemo','https://www.pinterest.com/pin/670895675758108130/'),('03 / Kaplumbağa & plastik','https://www.pinterest.com/pin/881861170807378464/'),('Mandy Barker / SOUP','https://www.mandy-barker.com/soup-2'),('Alejandro Durán / Washed Up','https://alejandroduran.com/photoseries')])+f'''</div></section><section class="source-section"><h2>05 / SCRIBBLE</h2><p>{t('002 / Recycle, muham²ed tarafından geliştirilen bir tasarım konseptidir. Atık toplama servisi veya resmî çevre kuruluşu değildir. Logo serinin ortak işaretidir; bu dünyanın kimliği bağımsızdır.','002 / Recycle is a design concept developed by muham²ed. It is not a waste collection service or official environmental organisation. The logo is the shared series mark; this world’s identity is independent.')}</p><p>Barlow Condensed / Space Grotesk / IBM Plex Mono — SIL Open Font License.</p></section></main>'''
(p/'references.html').write_text(head.replace('<title>Scribble / 002 — Recycle</title>','<title>Kaynaklar — Scribble / 002</title>')+nav+refs+foot+'</body></html>')
